action.query:
SELECT SUM(CASE WHEN ORDER_STATUS = 'Cancelled' THEN 1 ELSE 0 END) / COUNT(*)::FLOAT AS overall_cancellation_rate, AVG(CASE WHEN ORDER_STATUS = 'Delivered' THEN DELIVERY_TIME_MIN::FLOAT ELSE NULL END) AS overall_avg_delivery_time_delivered
FROM ZOMATO_DLR.SOURCES.ORDERS
WHERE ORDER_DATE >= '2025-01-01' AND ORDER_DATE < '2026-01-01';
